func main() {
	if err := run(os.Args[1:], nil); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}

// run executes the CLI with given arguments and database connection.
// If db is nil, it creates a test database.
func run(args []string, db *gorm.DB) error {
	// Create a new database if none provided
	if db == nil {
		testDB := testutil.NewTestDB(nil)
		db = testDB
	}

	// Parse command line flags
	cmd := flag.NewFlagSet("csuite-inbox", flag.ContinueOnError)

	// Common flags
	help := cmd.Bool("help", false, "Show help")

	// Subcommands
	sendCmd := flag.NewFlagSet("send", flag.ContinueOnError)
	from := sendCmd.String("from", "", "Message sender")
	to := sendCmd.String("to", "", "Message recipient")
	subject := sendCmd.String("subject", "", "Message subject")
	priority := sendCmd.String("priority", "", "Message priority")
	msgType := sendCmd.String("type", "", "Message type")
	body := sendCmd.String("body", "", "Message body")

	listCmd := flag.NewFlagSet("list", flag.ContinueOnError)
	agent := listCmd.String("agent", "", "Agent to list messages for")

	archiveCmd := flag.NewFlagSet("archive", flag.ContinueOnError)
	id := archiveCmd.String("id", "", "Message ID to archive")

	watchCmd := flag.NewFlagSet("watch", flag.ContinueOnError)
	watchAgent := watchCmd.String("agent", "", "Agent to watch for messages")

	if len(args) < 1 {
		return fmt.Errorf("no subcommand specified")
	}

	switch args[0] {
	case "send":
		if err := sendCmd.Parse(args[1:]); err != nil {
			return err
		}
		if *help {
			sendCmd.Usage()
			return nil
		}
		if *from == "" {
			return fmt.Errorf("--from is required")
		}
		// Create message in DB
		msg := inbox.Message{
			From:     *from,
			To:       *to,
			Subject:  *subject,
			Priority: *priority,
			Type:     *msgType,
			Body:     *body,
		}
		if err := db.Create(&msg).Error; err != nil {
			return err
		}
		fmt.Printf("Message created with ID: %s\n", msg.ID)
		return nil

	case "list":
		if err := listCmd.Parse(args[1:]); err != nil {
			return err
		}
		if *help {
			listCmd.Usage()
			return nil
		}
		if *agent == "" {
			return fmt.Errorf("--agent is required")
		}
		// List unread messages for agent
		var messages []inbox.Message
		db.Where("to = ? AND archived = ?", *agent, false).Find(&messages)
		for _, msg := range messages {
			fmt.Printf("ID: %s, From: %s, Subject: %s\n", msg.ID, msg.From, msg.Subject)
		}
		return nil

	case "archive":
		if err := archiveCmd.Parse(args[1:]); err != nil {
			return err
		}
		if *help {
			archiveCmd.Usage()
			return nil
		}
		if *id == "" {
			return fmt.Errorf("--id is required")
		}
		// Archive message
		var msg inbox.Message
		if err := db.First(&msg, *id).Error; err != nil {
			return err
		}
		msg.Archived = true
		db.Save(&msg)
		fmt.Printf("Message %s archived\n", *id)
		return nil

	case "watch":
		if err := watchCmd.Parse(args[1:]); err != nil {
			return err
		}
		if *help {
			watchCmd.Usage()
			return nil
		}
		if *watchAgent == "" {
			return fmt.Errorf("--agent is required")
		}
		// Watch for messages (simulated)
		fmt.Printf("Watching for messages for agent: %s\n", *watchAgent)
		// Simulate watching - in real implementation this would be more complex
		return nil

	default:
		return fmt.Errorf("unknown subcommand: %s", args[0])
	}
}"}

