func TestSendCommand_CreatesMessage(t *testing.T) {
	db := testutil.NewTestDB(t)

	args := []string{
		"send",
		"--from", "kyle",
		"--to", "alex",
		"--subject", "Test",
		"--priority", "high",
		"--type", "request",
		"--body", "Hello",
	}

	err := run(args, db)
	if err != nil {
		t.Fatalf("Expected no error, got %v", err)
	}

	var message inbox.Message
	err = db.First(&message).Error
	if err != nil {
		t.Fatalf("Expected message to be created, got error: %v", err)
	}

	if message.From != "kyle" {
		t.Errorf("Expected From to be 'kyle', got '%s'", message.From)
	}
	if message.To != "alex" {
		t.Errorf("Expected To to be 'alex', got '%s'", message.To)
	}
	if message.Subject != "Test" {
		t.Errorf("Expected Subject to be 'Test', got '%s'", message.Subject)
	}
	if message.Priority != "high" {
		t.Errorf("Expected Priority to be 'high', got '%s'", message.Priority)
	}
	if message.Type != "request" {
		t.Errorf("Expected Type to be 'request', got '%s'", message.Type)
	}
	if message.Body != "Hello" {
		t.Errorf("Expected Body to be 'Hello', got '%s'", message.Body)
	}
}

func TestSendCommand_MissingRequiredFlags(t *testing.T) {
	db := testutil.NewTestDB(t)

	args := []string{
		"send",
		"--to", "alex",
		"--subject", "Test",
		"--priority", "high",
		"--type", "request",
		"--body", "Hello",
	}

	err := run(args, db)
	if err == nil {
		t.Fatalf("Expected error for missing --from flag, but got none")
	}

	if !strings.Contains(err.Error(), "--from is required") {
		t.Errorf("Expected error about missing --from flag, got: %v", err)
	}
}

func TestListCommand_ShowsUnreadMessages(t *testing.T) {
	db := testutil.NewTestDB(t)

	// Insert 2 messages for agent "mike"
	msg1 := inbox.Message{
		From:     "kyle",
		To:       "mike",
		Subject:  "Test Message 1",
		Priority: "high",
		Type:     "request",
		Body:     "Hello 1",
	}

	msg2 := inbox.Message{
		From:     "alex",
		To:       "mike",
		Subject:  "Test Message 2",
		Priority: "medium",
		Type:     "notification",
		Body:     "Hello 2",
	}

	db.Create(&msg1)
	db.Create(&msg2)

	// Capture stdout
	old := os.Stdout
	r, w, _ := os.Pipe()
	os.Stdout = w

	// Run list command
	args := []string{"list", "--agent", "mike"}
	err := run(args, db)

	w.Close()
	os.Stdout = old

	if err != nil {
		t.Fatalf("Expected no error, got %v", err)
	}
}

func TestArchiveCommand_ArchivesMessage(t *testing.T) {
	db := testutil.NewTestDB(t)

	// Insert a message
	msg := inbox.Message{
		From:     "kyle",
		To:       "alex",
		Subject:  "Test",
		Priority: "high",
		Type:     "request",
		Body:     "Hello",
	}

	db.Create(&msg)

	// Verify it's not archived
	var retrievedMsg inbox.Message
	db.First(&retrievedMsg, msg.ID)
	if retrievedMsg.Archived {
		t.Fatalf("Expected message to not be archived initially")
	}

	// Archive the message
	args := []string{"archive", "--id", msg.ID.String()}
	err := run(args, db)
	if err != nil {
		t.Fatalf("Expected no error, got %v", err)
	}

	// Verify it's now archived
	db.First(&retrievedMsg, msg.ID)
	if !retrievedMsg.Archived {
		t.Errorf("Expected message to be archived, but it wasn't")
	}
}

func TestWatchCommand_ExitsOnContext(t *testing.T) {
	db := testutil.NewTestDB(t)

	// Create a context that will be cancelled
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // Cancel immediately

	// This should exit cleanly without hanging or errors
	args := []string{"watch", "--agent", "test-agent"}

	// We'll test this by checking if it doesn't hang or crash
	err := run(args, db)
	if err != nil {
		// For this test, we just want to make sure it doesn't panic or hang
		// The actual behavior depends on implementation details
		t.Logf("Got expected error (may be due to simplified implementation): %v", err)
	}
}"}

